/* computed signals: a square wave of n cycles between x0 and x1 (hi/lo y); a sine whose amplitude and cycles are given */
const AE_square=(x0,x1,n,hi,lo)=>{const p=[],d=(x1-x0)/n;for(let i=0;i<n;i++){const a=x0+i*d;p.push([a,lo],[a,hi],[a+d/2,hi],[a+d/2,lo]);}p.push([x1,lo]);return p};
const AE_sine=(x0,x1,cyc,amp,yc,N=160)=>{const p=[];for(let i=0;i<=N;i++){const t=i/N;p.push([x0+t*(x1-x0),yc-amp*Math.sin(2*Math.PI*cyc*t)]);}return p};
